{"code": "for (const pat of ["S1942PrePsiFive", "reducedQPilotAnchor", "The reduced anchor's x-mu layer"]) {
  try {
    const r = await tools.grep({ pattern: pat, path: "D:\\lean\\tmp" });
    console.log(`### ${pat}: ${r.matches.length} matches`);
    const byFile: Record<string, number> = {};
    for (const m of r.matches) byFile[m.path] = (byFile[m.path]||0)+1;
    console.log(Object.entries(byFile).slice(0,12).map(([f,c])=>`  ${c}  ${f}`).join("\n"));
  } catch(e) { console.log(`### ${pat}: ${e}`); }
}
", "description": "Grep tmp tree for lost ledger strings"}

